<?php
declare(strict_types=1);
require __DIR__.'/cms/library.php';
$publishedFile=__DIR__.'/storage/site.json';
$published=is_file($publishedFile)?json_decode((string)file_get_contents($publishedFile),true):null;
$live=is_array($published)&&!empty($published['published'])&&is_array($published['data']??null);
$kind=($_GET['type']??'photos')==='videos'?'videos':'photos';
$title=$kind==='photos'?'Image Gallery':'Video Gallery';
$items=$live?($published['data'][$kind==='photos'?'gallery':'videos']??[]):(lash_data()[$kind]??[]);
if (!is_array($items))$items=[];
function img_class(string $ref): string{return 'ph ph-'.preg_replace('/[^a-zA-Z0-9_-]/','',substr($ref,3));}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="Official Lashirah <?=lash_escape($title)?>"><title><?=lash_escape($title)?> · Lashirah</title><link rel="stylesheet" href="/assets/gallery-media.css"><link rel="stylesheet" href="/cms/media.php"><style>*{box-sizing:border-box}body{margin:0;background:#081328;color:#fff;font-family:system-ui,-apple-system,sans-serif}header{padding:26px max(20px,calc((100vw - 1120px)/2));background:#101e37;border-bottom:1px solid #263a57}a{color:#e8bd6c}header a{text-decoration:none}main{max-width:1160px;margin:40px auto;padding:0 20px}h1{font-size:clamp(28px,5vw,48px);margin:0 0 12px}.tabs{display:flex;gap:12px;margin:25px 0;flex-wrap:wrap}.tabs a{padding:12px 20px;border:1px solid #425671;border-radius:999px;text-decoration:none}.tabs .active{background:#d5b477;color:#101629}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(270px,1fr));gap:20px}.card{margin:0;background:#15243d;border:1px solid #314766;border-radius:15px;overflow:hidden}.card img,.card .ph{display:block;width:100%;aspect-ratio:16/10;object-fit:cover;background-size:cover;background-position:center}.card figcaption{padding:15px}.video{width:100%;aspect-ratio:16/9;border:0;display:block}.empty{padding:32px;background:#15243d;border-radius:15px;color:#c8d5e8}</style></head><body><header><a href="/">← Lashirah / Official website</a></header><main><h1><?=lash_escape($title)?></h1><p>Explore Lashirah's journey, events and achievements.</p><nav class="tabs"><a class="<?=$kind==='photos'?'active':''?>" href="/gallery.php?type=photos">Image Gallery</a><a class="<?=$kind==='videos'?'active':''?>" href="/gallery.php?type=videos">Video Gallery</a></nav><?php if(!$items): ?><div class="empty">New <?=strtolower(lash_escape($title))?> content will appear here soon.</div><?php else: ?><div class="grid"><?php foreach($items as $item): if(!is_array($item))continue;?><figure class="card"><?php if($kind==='photos'):
$src=(string)($item['src']??$item['url']??'');$caption=(string)($item['caption']??'');
if(str_starts_with($src,'ph:')): ?><div role="img" class="<?=lash_escape(img_class($src))?>" aria-label="<?=lash_escape($caption)?>"></div><?php elseif(str_starts_with($src,'/uploads/gallery/')): ?><img loading="lazy" src="<?=lash_escape($src)?>" alt="<?=lash_escape($caption)?>"><?php endif;?><figcaption><?=lash_escape($caption)?></figcaption><?php else:
$source=(string)($item['src']??'');$id=str_starts_with($source,'youtube:')?substr($source,8):(string)($item['youtube_id']??'');
if(preg_match('/^[a-zA-Z0-9_-]{11}$/D',$id)): ?><iframe class="video" loading="lazy" src="https://www.youtube-nocookie.com/embed/<?=lash_escape($id)?>" title="<?=lash_escape((string)($item['title']??'YouTube video'))?>" referrerpolicy="strict-origin-when-cross-origin" allow="accelerometer; autoplay; encrypted-media; picture-in-picture; web-share" allowfullscreen></iframe><?php else: ?><div class="ph" style="display:grid;place-items:center">Video available on the homepage</div><?php endif;?><figcaption><?=lash_escape((string)($item['title']??''))?></figcaption><?php endif ?></figure><?php endforeach ?></div><?php endif ?></main></body></html>